 private static Dictionary<string,(string Error,string Data)> Load(){using var memory=new MemoryStream(Convert.FromBase64String(""));using var gzip=new GZipStream(memory,CompressionMode.Decompress);using var reader=new StreamReader(gzip);var result=new Dictionary<string,(string,string)>();foreach(var line in reader.ReadToEnd().Split('\n')){var parts=line.Split('|');if(parts.Length!=3)throw new InvalidOperationException("Corrupt component query reference");result.Add(parts[0],(parts[1],parts[2]));}return result;}
